public class DaemonThreadDemo {
    private static void pause() {
        try {
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
    static class Gill extends Thread {
        @Override
        public void run() {
            System.out.println("Gill is inspecting the pitch");
            pause();
            System.out.println("Gill is warming up");
            pause();
            System.out.println("Gill is doing catching practice");
            pause();
            System.out.println("Gill is doing batting practice");
            pause();
            System.out.println("Gill is doing bowling practice");
            pause();
            System.out.println("Gill has finished and is going to the hotel");
        }
    }
    static class BattingCoach extends Thread {
        @Override
        public void run() {
            while (true) {
                System.out.println("Batting coach is assisting Gill");
                pause();
            }
        }
    }
    static class BowlingCoach extends Thread {
        @Override
        public void run() {
            while (true) {
                System.out.println("Bowling coach is assisting Gill");
                pause();
            }
        }
    }
    public static void main(String[] args) {
        Gill gill = new Gill();
        BattingCoach battingCoach = new BattingCoach();
        BowlingCoach bowlingCoach = new BowlingCoach();
        battingCoach.setName("Batting Coach");
        bowlingCoach.setName("Bowling Coach");
        battingCoach.setDaemon(true);
        bowlingCoach.setDaemon(true);
        gill.start();
        battingCoach.start();
        bowlingCoach.start();
    }
}

Thread helper = new Thread();
helper.setDaemon(true);
helper.start();

